mapper.select:
SELECT u.id as id, u.create_time as registerTime, u.username as name, u.status as state, u.user_type as type,
       '通过' as applyState, u.create_time as applyTime
FROM sys_user u


        AND u.username like CONCAT('%', #{listDto.name}, '%')


        AND u.user_type = #{listDto.type}


        AND u.create_time > #{listDto.date}


ORDER BY u.create_time DESC
LIMIT #{listDto.pageSize} OFFSET #{listDto.currentPage}

SELECT COUNT(*)
FROM sys_user


        AND username like CONCAT('%', #{listDto.name}, '%')


        AND user_type = #{listDto.type}


        AND create_time >= #{listDto.date}
